<?php $e=static fn(mixed $v):string=>htmlspecialchars((string)$v,ENT_QUOTES|ENT_SUBSTITUTE,'UTF-8'); ?>
<!doctype html><html lang="de"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title><?= $e($area['name']) ?> – MeldeVerkehr</title>
<style>body{font-family:system-ui,sans-serif;background:#f5f7fa;color:#172033;margin:0}main{max-width:1000px;margin:28px auto;padding:20px}.card{background:#fff;border:1px solid #dfe5ec;border-radius:15px;padding:22px;margin-bottom:14px}.message,.error{padding:12px;border-radius:9px;margin-bottom:12px}.message{border:1px solid #8fb799}.error{border:1px solid #c99}table{width:100%;border-collapse:collapse}td,th{padding:8px;border-bottom:1px solid #e5e9ee;text-align:left}button{padding:10px 14px;border:0;border-radius:9px;background:#172033;color:white;font-weight:700}.muted{color:#66758a}input{padding:9px;border:1px solid #bac5d1;border-radius:8px}</style></head><body><main>
<p><a href="/problem-areas">← Problemstellen</a></p><h1><?= $e($area['name']) ?></h1><p><?= $e(trim(($area['street']??'').' '.($area['city']??''))) ?> · Radius <?= $e($area['radius_m']) ?> m</p>
<?php if($message):?><div class="message"><?= $e($message) ?></div><?php endif;?><?php if($error):?><div class="error"><?= $e($error) ?></div><?php endif;?>
