<section class="card"><h2>Aktuelle Kennzahlen</h2><p><strong><?= $e($area['metrics']['case_count']) ?></strong> zugeordnete Vorgänge</p><?php foreach($area['metrics']['offense_category_counts'] as $r):?><p><?= $e($r['label']) ?>: <?= $e($r['count']) ?></p><?php endforeach;?></section>
<section class="card"><h2>Zugeordnete Vorgänge</h2><table><tr><th>Vorgang</th><th>Zeit</th><th>Tatbestand</th><th>Distanz</th></tr><?php foreach($area['cases'] as $c):?><tr><td><a href="/cases/<?= rawurlencode($c['id']) ?>"><?= $e($c['public_number']) ?></a></td><td><?= $e($c['observed_from']??'') ?></td><td><?= $e($c['offense_title']??'–') ?></td><td><?= $e($c['distance_m']) ?> m</td></tr><?php endforeach;?></table></section>
<section class="card"><h2>Anonymisierten kommunalen Problembericht erzeugen</h2><p class="muted">Der Report enthält nur Aggregationen. Keine Kennzeichen, keine Halterdaten, keine Vorgangs-IDs und standardmäßig keine Fotos.</p><form method="post" action="/problem-areas/<?= rawurlencode($area['id']) ?>/reports"><input type="hidden" name="_csrf" value="<?= $e($csrf) ?>"><label>Von <input type="date" name="from" required></label> <label>Bis <input type="date" name="to" required></label><br><button type="submit">Bericht erzeugen</button></form></section>
</main></body></html>